WITH recent_web_events AS (SELECT *, CONCAT(event_type, ', ', page) AS event_type_page FROM web_events WHERE TO_DATE(event_time) >= '2024-07-24' AND page = '/cart' AND page = '/home'), web_events_stats AS (SELECT page, COUNT(duration_sec) AS duration_sec_count FROM recent_web_events GROUP BY page) SELECT page, duration_sec_count FROM web_events_stats WHERE duration_sec_count >= 5 ORDER BY duration_sec_count DESC;
